1	// Red-first fixture tests for the gcec pack's checks, runnable by this repo's own
2	// `npm test` (no imports from the gitignored .claudinite mount — see the check
3	// module's header). Each rule is shown firing on a violating fixture and staying
4	// quiet on a clean one.
5	import test from 'node:test';
6	import assert from 'node:assert/strict';
7	import testOfflineListSync from './test-offline-list-sync.mjs';
8	import customSourcesFlat from './custom-sources-flat.mjs';
9	import npmTestGlobCoverage from './npm-test-glob-coverage.mjs';
10	import pipelineSiteAgnostic from './pipeline-site-agnostic.mjs';
11	import regenArtifactsMergeOurs from './regen-artifacts-merge-ours.mjs';
12	
13	function ctx({ files = [], pkg }) {
14	  const disk = new Set([...files, 'package.json']);
15	  return {
16	    files,
17	    read: (p) => (p === 'package.json' ? JSON.stringify(pkg) : null),
18	    exists: (p) => disk.has(p),
19	  };
20	}
21	
22	const pkgWith = (offline) => ({ scripts: { 'test:offline': `node --test ${offline.join(' ')}` } });
23	
24	test('test-offline-list-sync: fires when a mirror test is missing from the list', () => {
25	  const findings = testOfflineListSync.run(
26	    ctx({
27	      files: ['extension-test/a.test.js', 'extension-test/b.test.js'],
28	      pkg: pkgWith(['extension-test/a.test.js']),
29	    }),
30	  );
31	  assert.equal(findings.length, 1);
32	  assert.match(findings[0].what, /missing extension-test\/b\.test\.js/);
33	  assert.equal(findings[0].severity, 'blocking');
34	});
35	
36	test('test-offline-list-sync: fires when the list names a file that does not exist', () => {
37	  const findings = testOfflineListSync.run(
38	    ctx({
39	      files: ['extension-test/a.test.js'],
40	      pkg: pkgWith(['extension-test/a.test.js', 'extension-test/gone.test.js']),
41	    }),
42	  );
43	  assert.equal(findings.length, 1);
44	  assert.match(findings[0].what, /extension-test\/gone\.test\.js, which does not exist/);
45	});
46	
47	test('test-offline-list-sync: quiet when list and tree agree (non-mirror entries ignored)', () => {
48	  const findings = testOfflineListSync.run(
49	    ctx({
50	      files: ['extension-test/a.test.js', 'dev/build/test/other.test.js'],
51	      pkg: pkgWith(['extension-test/a.test.js', 'dev/build/release/shipping-files.test.js']),
52	    }),
53	  );
54	  assert.deepEqual(findings, []);
55	});
56	
57	test('test-offline-list-sync: quiet when package.json has no test:offline script', () => {
58	  const findings = testOfflineListSync.run(
59	    ctx({ files: ['extension-test/a.test.js'], pkg: { scripts: {} } }),
60	  );
61	  assert.deepEqual(findings, []);
62	});
63	
64	// A context whose files ARE the keys of a path → content map, for the rules that
65	// read file text rather than package.json.
66	const treeCtx = (tree) => ({
67	  files: Object.keys(tree),
68	  read: (p) => (p in tree ? tree[p] : null),
69	  exists: (p) => p in tree,
70	});
71	
72	test('custom-sources-flat: fires on a subdirectory, a non-source file, and a pipeline file in custom/', () => {
73	  const findings = customSourcesFlat.run(
74	    treeCtx({
75	      'extension/event-extractors/custom/barby.js': '',
76	      'extension/event-extractors/custom/shared/util.js': '',
77	      'extension/event-extractors/custom/README.md': '',
78	      'extension/event-extractors/custom/generic-extractor.js': '',
79	    }),
80	  );
81	  assert.equal(findings.length, 3);
82	  assert.match(findings[0].what, /sits in a subdirectory/);
83	  assert.match(findings[1].what, /is not a per-site source/);
84	  assert.match(findings[2].what, /is a pipeline file/);
85	  assert.ok(findings.every((f) => f.severity === 'blocking'));
86	});
87	
88	test('custom-sources-flat: quiet on a flat tree of per-site sources beside the pipeline', () => {
89	  const findings = customSourcesFlat.run(
90	    treeCtx({
91	      'extension/event-extractors/custom/barby.js': '',
92	      'extension/event-extractors/custom/tel-aviv.js': '',
93	      'extension/event-extractors/generic-extractor.js': '',
94	      'extension/event-extractors/registry.js': '',
95	      'extension/event-extractors/helpers/dates.js': '',
96	      'extension/event-extractors/load-order.generated.json': '',
97	    }),
98	  );
99	  assert.deepEqual(findings, []);
100	});
101	
102	// npm-test-glob-coverage reads package.json's `test` (and `test:e2e`) scripts, so its
103	// fixtures pair a file list with a scripts object — the real shape of both scripts,
104	// quoted globs included.
105	const globCtx = (files, scripts) =>
106	  ctx({ files, pkg: { scripts } });
107	
108	const SCRIPTS = {
109	  test: 'node --disable-warning=X --test "extension-test/**/*.test.js" "dev/build/test/**/*.test.js" ".claudinite/local/packs/**/*.test.mjs" "dev/requirements/logic/**/*.test.js" dev/requirements/requirements-coverage.test.js',
110	  'test:e2e': 'node --test "dev/requirements/heavy/**/*.test.js"',
111	};
112	
113	test('npm-test-glob-coverage: fires on a test file no `test` pattern reaches', () => {
114	  const findings = npmTestGlobCoverage.run(
115	    globCtx(
116	      ['extension-test/host-policy.test.js', 'dev/security/csp.test.js'],
117	      SCRIPTS,
118	    ),
119	  );
120	  assert.equal(findings.length, 1);
121	  assert.equal(findings[0].file, 'dev/security/csp.test.js');
122	  assert.match(findings[0].what, /reached by no pattern/);
123	  assert.equal(findings[0].severity, 'blocking');
124	});
125	
126	test('npm-test-glob-coverage: quiet when every pattern shape reaches its files', () => {
127	  const findings = npmTestGlobCoverage.run(
128	    globCtx(
129	      [
130	        'extension-test/host-policy.test.js', // `**/` must match ZERO directories too
131	        'extension-test/events-popup/popup.test.js',
132	        'dev/build/test/load-order-generated.test.js',
133	        '.claudinite/local/packs/gcec/pack.test.mjs', // .mjs counts as a test file
134	        'dev/requirements/logic/product-requirements.test.js',
135	        'dev/requirements/requirements-coverage.test.js', // a literal path, not a glob
136	        'extension/host-policy.js', // not a test file at all
137	      ],
138	      SCRIPTS,
139	    ),
140	  );
141	  assert.deepEqual(findings, []);
142	});
143	
144	test('npm-test-glob-coverage: the heavy e2e suite is exempt via scripts["test:e2e"]', () => {
145	  const heavy = 'dev/requirements/heavy/extension-load.chrome.test.js';
146	  assert.deepEqual(npmTestGlobCoverage.run(globCtx([heavy], SCRIPTS)), []);
147	  // …and only because test:e2e declares it: drop that script and the carve-out goes.
148	  const findings = npmTestGlobCoverage.run(globCtx([heavy], { test: SCRIPTS.test }));
149	  assert.equal(findings.length, 1);
150	  assert.equal(findings[0].file, heavy);
151	});
152	
153	test('npm-test-glob-coverage: quiet when the test script is not a `node --test` runner', () => {
154	  const findings = npmTestGlobCoverage.run(
155	    globCtx(['dev/security/csp.test.js'], { test: 'jest' }),
156	  );
157	  assert.deepEqual(findings, []);
158	});
159	
160	// pipeline-site-agnostic reads the host list out of the repo, so every fixture
161	// tree carries a host-lists.json — the check follows that declaration, never a
162	// copy of it.
163	const HOSTS = JSON.stringify({
164	  supportedDomains: ['stubhub.com', 'tel-aviv.gov.il', 'visit.tel-aviv.gov.il', 'lu.ma'],
165	});
166	const pipelineCtx = (tree) => treeCtx({ 'extension/host-lists.json': HOSTS, ...tree });
167	
168	test('pipeline-site-agnostic: fires on a host in shipped pipeline code, in the generic extractor and in a helper', () => {
169	  const findings = pipelineSiteAgnostic.run(
170	    pipelineCtx({
171	      'extension/event-extractors/generic-extractor.js':
172	        'function read(doc) {\n  if (host.endsWith("stubhub.com")) return special(doc);\n  return generic(doc);\n}\n',
173	      'extension/event-extractors/helpers/derive-timezone.js':
174	        'const OVERRIDE = { "visit.tel-aviv.gov.il": "Asia/Jerusalem" };\n',
175	    }),
176	  );
177	  assert.equal(findings.length, 2);
178	  assert.equal(findings[0].file, 'extension/event-extractors/generic-extractor.js');
179	  assert.equal(findings[0].line, 2); // the blanked comments keep line numbers true
180	  assert.match(findings[0].what, /names the supported site stubhub\.com/);
181	  // the longest matching entry wins, not the one it contains
182	  assert.match(findings[1].what, /visit\.tel-aviv\.gov\.il/);
183	  assert.ok(findings.every((f) => f.severity === 'blocking'));
184	});
185	
186	test('pipeline-site-agnostic: fires on a host hidden in a URL string (the `//` must not read as a comment)', () => {
187	  const findings = pipelineSiteAgnostic.run(
188	    pipelineCtx({
189	      'extension/event-extractors/assemble-events.js':
190	        'const FEED = "https://lu.ma/api/events";\n',
191	    }),
192	  );
193	  assert.equal(findings.length, 1);
194	  assert.equal(findings[0].line, 1);
195	  assert.match(findings[0].what, /lu\.ma/);
196	});
197	
198	test('pipeline-site-agnostic: quiet when the sites are only cited in comments, or live in custom/', () => {
199	  const findings = pipelineSiteAgnostic.run(
200	    pipelineCtx({
201	      // citing where a generic pattern was observed is how this codebase records
202	      // evidence — both comment forms, and one on the same line as real code
203	      'extension/event-extractors/generic-extractor.js':
204	        '// or is merely the site\'s domain ("stubhub.com" is not a venue).\n' +
205	        '/* seen on visit.tel-aviv.gov.il\n   and lu.ma */\n' +
206	        'const venue = readVenue(doc); // not stubhub.com-specific\n',
207	      // per-site knowledge belongs here, and this check must never flag it
208	      'extension/event-extractors/custom/stubhub.js':
209	        'GCal.sources.push({ matches: (h) => /(^|\\.)stubhub\\.com$/.test(h) });\n',
210	      // a host-shaped substring is not the host
211	      'extension/event-extractors/helpers/text.js': 'const s = "notstubhub.combo";\n',
212	      // non-.js pipeline files are out of scope
213	      'extension/event-extractors/load-order.generated.json': '["stubhub.com"]',
214	    }),
215	  );
216	  assert.deepEqual(findings, []);
217	});
218	
219	test('pipeline-site-agnostic: quiet when the host list is missing or declares nothing', () => {
220	  const tree = {
221	    'extension/event-extractors/generic-extractor.js': 'if (h === "stubhub.com") {}\n',
222	  };
223	  assert.deepEqual(pipelineSiteAgnostic.run(treeCtx(tree)), []);
224	  assert.deepEqual(
225	    pipelineSiteAgnostic.run(treeCtx({ ...tree, 'extension/host-lists.json': '{"supportedDomains":[]}' })),
226	    [],
227	  );
228	});
229	
230	// regen-artifacts-merge-ours reads .gitattributes out of the fixture tree, so each
231	// tree pairs the artifacts with the driver list that is supposed to name them. The
232	// live repo's list, verbatim in shape, is the clean baseline every fixture varies.
233	const GITATTRIBUTES = [
234	  '# Generated/derived files — regenerated by `npm run regen`, never hand-merged.',
235	  '# extension/event-extractors/not-a-real-entry.json merge=ours   <- a comment, not an entry',
236	  'dev/requirements/extractor/data/**/*.html linguist-vendored',
237	  'extension/event-extractors/load-order.generated.json                merge=ours',
238	  'dev/requirements/extractor/generic-coverage/generic-coverage.baseline.GENERATED.json   merge=ours',
239	  'dev/requirements/popup/cases/*.png                                              merge=ours',
240	  'dev/requirements/icon/cases/*.png                                               merge=ours',
241	].join('\n');
242	
243	const attrCtx = (files, gitattributes = GITATTRIBUTES) => ({
244	  files,
245	  allFiles: files,
246	  read: (p) => (p === '.gitattributes' ? gitattributes : null),
247	  exists: () => false,
248	});
249	
250	test("regen-artifacts-merge-ours: fires on a new image kind's snapshots and on an unlisted generated file", () => {
251	  const findings = regenArtifactsMergeOurs.run(
252	    attrCtx([
253	      // a kind added by the self-contained folder drop kinds.js auto-discovers —
254	      // .gitattributes still names only popup/ and icon/
255	      'dev/requirements/badge/cases/badge-states.12.1.png',
256	      'extension/event-extractors/second-list.generated.json',
257	    ]),
258	  );
259	  assert.equal(findings.length, 2);
260	  assert.match(findings[0].what, /dev\/requirements\/badge\/cases\/badge-states\.12\.1\.png/);
261	  // the fix names the DIRECTORY glob for a snapshot, the file itself for a generated one
262	  assert.match(findings[0].fix, /dev\/requirements\/badge\/cases\/\*\.png merge=ours/);
263	  assert.match(findings[1].fix, /extension\/event-extractors\/second-list\.generated\.json merge=ours/);
264	  assert.ok(findings.every((f) => f.severity === 'blocking'));
265	});
266	
267	test('regen-artifacts-merge-ours: quiet on the repo\'s real artifact set', () => {
268	  const findings = regenArtifactsMergeOurs.run(
269	    attrCtx([
270	      'extension/event-extractors/load-order.generated.json',
271	      'dev/requirements/popup/cases/count-label.8.1.png',
272	      'dev/requirements/icon/cases/toolbar-icon.10.1.png',
273	      'extension/events-popup/popup.js', // not an artifact at all
274	      'dev/build/release/store_artifacts/chrome-store-screenshot-1280x800.png', // a PNG outside <kind>/cases/
275	    ]),
276	  );
277	  assert.deepEqual(findings, []);
278	});
279	
280	test('regen-artifacts-merge-ours: leaves the GENERATED-marked files to the canon rule', () => {
281	  // basics/generated-merge-driver owns every name carrying the uppercase marker, so
282	  // this rule must stay silent on one even with no entry in .gitattributes at all.
283	  const findings = regenArtifactsMergeOurs.run(
284	    attrCtx(
285	      ['dev/requirements/extractor/generic-coverage/generic-coverage.GENERATED.md'],
286	      '# nothing on the ours driver here',
287	    ),
288	  );
289	  assert.deepEqual(findings, []);
290	});
291	
292	test('regen-artifacts-merge-ours: honors a basename-only pattern, and a `*` that must not cross a /', () => {
293	  // a pattern with no slash matches by basename at any depth (gitignore semantics)
294	  assert.deepEqual(
295	    regenArtifactsMergeOurs.run(attrCtx(['dev/requirements/popup/cases/count-label.8.1.png'], '*.png merge=ours')),
296	    [],
297	  );
298	  // a single `*` stops at the separator, so a path pattern does not reach a file
299	  // one directory deeper — only `**` does
300	  const deeper = ['extension/event-extractors/load-order.generated.json'];
301	  assert.equal(regenArtifactsMergeOurs.run(attrCtx(deeper, 'extension/*.generated.json merge=ours')).length, 1);
302	  assert.deepEqual(regenArtifactsMergeOurs.run(attrCtx(deeper, 'extension/**/*.generated.json merge=ours')), []);
303	});
304	
305	test('regen-artifacts-merge-ours: quiet when there are no regen artifacts in scope', () => {
306	  assert.deepEqual(regenArtifactsMergeOurs.run(attrCtx(['extension/events-popup/popup.js'])), []);
307	});
